#!/usr/bin/env bash
set -Eeuo pipefail
ROOT="/home/mwynn/nfl_data_engine"
cd "$ROOT"
PY="$ROOT/venv/bin/python"
MODULE="$ROOT/fanduel_injury_ingest.py"
DB="$ROOT/data/nfl.db"
LOCK="$ROOT/nfl_updater.lock"
EXPECTED_OLD="41cedf2cda8e7cfc862dc3f9c85fb931ef35cf3b4a627cbc5755afd5607b5bfd"
EXPECTED_NEW="8b8cd6f463c1ef354d3e20b54ffa53175e2ef51d221ba9bfe75a0598b6f006c2"
STAMP="$(date -u +%Y%m%dT%H%M%SZ)"
BACKDIR="$ROOT/backups/injury_consensus"
MOD_BAK="$BACKDIR/fanduel_injury_ingest_before_injury18_${STAMP}.py"
DB_BAK="$BACKDIR/nfl_before_injury18_${STAMP}.db"
mkdir -p "$BACKDIR"

exec 9>"$LOCK"
if ! flock -n 9; then echo "FAIL: nfl updater lock is busy; retry after updater finishes"; exit 1; fi

check_hash() { local f="$1" exp="$2"; local got; got="$(sha256sum "$f" | awk '{print $1}')"; [[ "$got" == "$exp" ]] || { echo "FAIL hash $f expected=$exp got=$got"; exit 1; }; }
protected() {
sha256sum app.py fanduel_nfl_ui_solver.py fanduel_slate_projection_attach_v5.py fanduel_solver_ready_pool.py updater.py live_ingest.py live_safe_poll.py live_orchestrator.py live_concurrency_gate.py wfs_live_view.py
}

echo "======================================================================"
echo "WFS NFL — NFL-INJURY-18 CONTROLLED WRITE"
echo "======================================================================"
echo "=== PREFLIGHT ==="
check_hash "$MODULE" "$EXPECTED_OLD"
test "$(systemctl is-active wfs.service)" = active
test "$(systemctl is-active wfs-nfl-live.service)" = active
protected > /tmp/injury18_protected_before.txt
cat /tmp/injury18_protected_before.txt
cp -a "$MODULE" "$MOD_BAK"
"$PY" - <<PYDB
import sqlite3
src=sqlite3.connect(r"$DB")
dst=sqlite3.connect(r"$DB_BAK")
src.backup(dst); dst.close(); src.close()
PYDB
echo "MODULE_BACKUP=$MOD_BAK"
echo "DB_BACKUP=$DB_BAK"

rollback() {
  rc=$?
  echo "NFL-INJURY-18 FAILURE — ROLLING BACK"
  cp -a "$MOD_BAK" "$MODULE" || true
  "$PY" - <<PYDB || true
import sqlite3
src=sqlite3.connect(r"$DB_BAK")
dst=sqlite3.connect(r"$DB")
src.backup(dst); dst.close(); src.close()
PYDB
  echo "ROLLBACK_MODULE_SHA=$(sha256sum "$MODULE" | awk '{print $1}')"
  exit "$rc"
}
trap rollback ERR

base64 -d > "$MODULE" <<'PAYLOAD'

PAYLOAD
chmod 755 "$MODULE"
check_hash "$MODULE" "$EXPECTED_NEW"
"$PY" -m py_compile "$MODULE"
echo "STAGED_MODULE_SHA=$EXPECTED_NEW"

# DB health before write
"$PY" - <<'PYDB'
import sqlite3
p='/home/mwynn/nfl_data_engine/data/nfl.db'
c=sqlite3.connect(p)
print('DB_INTEGRITY_BEFORE='+c.execute('PRAGMA integrity_check').fetchone()[0])
c.close()
PYDB

echo "=== RUN 1 ==="
"$PY" "$MODULE" | tee /tmp/injury18_run1.log
grep -q 'FANDUEL_INJURY_INGEST_V2_STATUS=PASS' /tmp/injury18_run1.log

echo "=== RUN 2 / IDEMPOTENCE ==="
"$PY" "$MODULE" | tee /tmp/injury18_run2.log
grep -q 'FANDUEL_INJURY_INGEST_V2_STATUS=PASS' /tmp/injury18_run2.log
grep -q '^INSERTED = 0$' /tmp/injury18_run2.log

"$PY" - <<'PYDB'
import sqlite3
p='/home/mwynn/nfl_data_engine/data/nfl.db'
c=sqlite3.connect(p)
cols=[r[1] for r in c.execute('PRAGMA table_info(injury_news_signals)')]
assert 'source_event_id' in cols and 'signal_key' in cols
assert c.execute("SELECT COUNT(*) FROM (SELECT signal_key FROM injury_news_signals WHERE signal_key IS NOT NULL GROUP BY signal_key HAVING COUNT(*)>1)").fetchone()[0] == 0
assert c.execute("SELECT COUNT(*) FROM injury_news_signals WHERE source='FANDUEL_RESEARCH' AND signal_key IS NOT NULL AND (source_event_id IS NULL OR trim(source_event_id)='')").fetchone()[0] == 0
print('DB_INTEGRITY_AFTER='+c.execute('PRAGMA integrity_check').fetchone()[0])
print('FANDUEL_ROWS='+str(c.execute("SELECT COUNT(*) FROM injury_news_signals WHERE source='FANDUEL_RESEARCH'").fetchone()[0]))
print('FANDUEL_KEYED_ROWS='+str(c.execute("SELECT COUNT(*) FROM injury_news_signals WHERE source='FANDUEL_RESEARCH' AND signal_key IS NOT NULL").fetchone()[0]))
print('FANDUEL_LEGACY_UNKEYED_ROWS='+str(c.execute("SELECT COUNT(*) FROM injury_news_signals WHERE source='FANDUEL_RESEARCH' AND signal_key IS NULL").fetchone()[0]))
print('SIGNAL_SCHEMA_PROOF=PASS')
c.close()
PYDB

protected > /tmp/injury18_protected_after.txt
diff -u /tmp/injury18_protected_before.txt /tmp/injury18_protected_after.txt
check_hash "$MODULE" "$EXPECTED_NEW"
test "$(systemctl is-active wfs.service)" = active
test "$(systemctl is-active wfs-nfl-live.service)" = active
trap - ERR

echo "=== PROTECTED HASHES AFTER ==="
cat /tmp/injury18_protected_after.txt
echo "wfs.service=active"
echo "wfs-nfl-live.service=active"
echo "NFL_INJURY_18_STATUS=PASS"
